use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::{Read,Write},path::Path,process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/sparse-rns-screen";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-28-sparse-rns-screen";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn main(){let r=Path::new(R);let d=Path::new(D);if std::env::args().nth(1).as_deref()==Some("verify"){let v=read(d.join("artifact-index.json"));let mut text=String::new();for(f,h)in v.as_object().unwrap(){assert!(!f.contains('\n')&&!f.contains('\\'));text.push_str(&format!("{}  artifacts/{f}\n",h.as_str().unwrap()));}let mut child=Command::new("sha256sum").args(["--check","--strict","-"]).current_dir(d).stdin(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(text.as_bytes()).unwrap();assert!(child.wait().unwrap().success());println!("Independent GNU check: {} artifact hashes",v.as_object().unwrap().len());return}
    for(p,h)in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let a=read(r.join("analysis.json"));assert_eq!(a["native_trial_justified"],false);assert_eq!(a["proof_ledger_unchanged"],12524);let fields=a["fields"].as_array().unwrap();assert_eq!(fields.len(),2);assert_eq!(fields.iter().map(|f|f["total_reductions"].as_u64().unwrap()).sum::<u64>(),34400);for f in fields{assert_eq!(f["hybrid_work"][0]["total_logical_sites"],945);}
    let s=read(r.join("search.json"));let mut score=0u64;for side in["left","right"]{let offsets=s[side]["offsets"].as_array().unwrap();let weights:Vec<u64>=offsets.iter().map(|v|{let mut k=v.as_i64().unwrap();let mut n=0;while k!=0{if k&1!=0{k-=2-k.rem_euclid(4);n+=1}k/=2}n}).collect();let mut c:u64=weights.iter().map(|w|4*(2*w+2)).sum();c+=weights[..4].iter().sum::<u64>()*5;for inv in s[side]["inverse_details"].as_array().unwrap(){let j=inv["j"].as_u64().unwrap()as usize;c+=inv["proxy_weight"].as_u64().unwrap()+2*weights[j]+4;}assert_eq!(c,s[side]["proxy_score"].as_u64().unwrap());score+=c;}assert_eq!(score,510);assert_eq!(s["minimum_combined_proxy"],510);
    fs::write(r.join("closeout.json"),serde_json::to_vec_pretty(&json!({"status":"complete","exact_reductions":34400,"conversion_integers":2048,"new_tests":3,"successful_tests_repeated":false,"SDK_requests":0,"new_exports":0,"proof_ledger_unchanged":12524,"adopted":false,"goal_achieved":false,"owned_jobs":[],"owned_cloud_resources":[]})).unwrap()).unwrap();fs::create_dir_all(d.join("artifacts")).unwrap();let mut index=BTreeMap::new();for e in fs::read_dir(r).unwrap(){let e=e.unwrap();let p=e.path();if !e.file_type().unwrap().is_file(){continue}let name=e.file_name().to_string_lossy().to_string();if name=="close.log"||name=="archive-verification.log"||!(["rs","json","log","md"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or(""))){continue}let dest=d.join("artifacts").join(&name);fs::copy(&p,&dest).unwrap();assert_eq!(hash(&p),hash(&dest));index.insert(name,hash(&dest));}fs::write(d.join("artifact-index.json"),serde_json::to_vec_pretty(&json!(index)).unwrap()).unwrap();println!("Closed sparse RNS screen;34400reductions;{}artifact hashes;ledger12524 unchanged",index.len());
}
